// Xcode 27 rejects any target whose IPHONEOS_DEPLOYMENT_TARGET is below 15.0, and
// a few pods (RNCAsyncStorage's resource bundle, ReachabilitySwift) still declare
// 12.0 / 13.4, so the Release build fails. Raise every pod target to at least the
// app's own minimum. ios/ is regenerated by `expo prebuild --clean`, so this has
// to live in a config plugin rather than a hand edit to ios/Podfile.
const { withPodfile } = require('expo/config-plugins');

const MIN_IOS = '16.4'; // the Podfile's platform :ios default
const MARKER = '# with-pod-deployment-target';

module.exports = function withPodDeploymentTarget(config) {
  return withPodfile(config, (cfg) => {
    let podfile = cfg.modResults.contents;
    if (podfile.includes(MARKER)) return cfg;

    const hook = `post_install do |installer|
    ${MARKER}
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |bc|
        current = bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        if current.nil? || Gem::Version.new(current) < Gem::Version.new('${MIN_IOS}')
          bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${MIN_IOS}'
        end
      end
    end
`;
    if (!podfile.includes('post_install do |installer|')) {
      throw new Error('with-pod-deployment-target: no post_install block in the Podfile');
    }
    podfile = podfile.replace('post_install do |installer|\n', hook);
    cfg.modResults.contents = podfile;
    return cfg;
  });
};
